const goals = items.map(i => {
  const current = Number(i.json.current_value) || 0;
  const target = Number(i.json.target_value) || 0;
  const pct = target > 0 ? Math.round((current / target) * 1000) / 10 : 0;
  return {
    goal_name: i.json.goal_name,
    unit: i.json.unit,
    current_value: current,
    target_value: target,
    pct_to_goal: pct,
    on_track: pct >= 50
  };
});
const summaryLines = goals.map(g => `${g.goal_name}: ${g.current_value}/${g.target_value} ${g.unit} (${g.pct_to_goal}% to goal, ${g.on_track ? 'on track' : 'behind'})`);
return [{ json: { goals, summary_text: summaryLines.join('\n') } }];
